/// <reference path="../common/basic-auditing.ts" />
/**
 * Used by Intent.Modules.NET\Modules\Intent.Modules.Entities.BasicAuditing
 *
 * Automatically applies the Basic Auditing stereotype (and its configured audit attributes) to a
 * newly created Class when the "Apply Basic Auditing to Entities" module setting is set to
 * "Automatically when created". Which of the 4 attributes get added, and what they are named, is
 * controlled by the "Include <Field>" switch settings (name only when included) - a disabled switch
 * excludes that attribute. This only affects brand-new Classes - it never renames or adds attributes
 * on a Class that is already audited.
 */
function execute(element) {
    const auditStereotypeId = "796ec2fb-cdb9-4f8e-b096-a4f72c7a7f93";
    const basicAudtingSettingsId = "e51c0868-816d-432b-9cc3-c597fdb1ef0d";
    const applyBasicAuditingFieldId = "43a36ffb-2085-4cf5-a255-f95c19368fa8";

    let applyBasicAuditing = application.getSettings(basicAudtingSettingsId)?.getField(applyBasicAuditingFieldId)?.value;
    if (applyBasicAuditing !== "automatically-when-created") {
        return;
    }

    if (!element.hasStereotype(auditStereotypeId)) {
        element.addStereotype(auditStereotypeId);
    }

    let userIdentifier = getUserIdentityType();
    ensureConfiguredAuditAttributes(element, userIdentifier, false);
}
execute(element);
